package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.countriesByLanguage
 */
public class LocaleUtils_countriesByLanguage_TriageGen1Test {

    @Test
    public void testCountriesByLanguage_NullInput() {
        // Testing the branch where languageCode is null
        List<Locale> result = LocaleUtils.countriesByLanguage(null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_ValidLanguage() {
        // Testing a known language code (e.g., "en") to trigger the search logic
        // This will cover the loop, the condition checking language, country length, and variant emptiness
        List<Locale> result = LocaleUtils.countriesByLanguage("en");

        assertNotNull(result);
        // Verify that all returned locales actually match the language code
        for (Locale locale : result) {
            assertEquals("en", locale.getLanguage());
            assertFalse("Country should not be empty", locale.getCountry().isEmpty());
            assertTrue("Variant should be empty", locale.getVariant().isEmpty());
        }
    }

    @Test
    public void testCountriesByLanguage_NonExistentLanguage() {
        // Testing a language code that does not exist in availableLocaleList
        // This covers the case where the loop finishes without adding any locales
        List<Locale> result = LocaleUtils.countriesByLanguage("xyz123");

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_CacheHit() {
        // Testing the branch where the result is already in the cCountriesByLanguage map
        // First call to populate the cache
        String lang = "fr";
        List<Locale> firstCall = LocaleUtils.countriesByLanguage(lang);

        // Second call to trigger the 'if (countries == null)' skip (cache hit)
        List<Locale> secondCall = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(secondCall);
        assertSame("The list should be the same instance from the cache", firstCall, secondCall);
    }

    @Test
    public void testCountriesByLanguage_EmptyString() {
        // Testing an empty string input
        List<Locale> result = LocaleUtils.countriesByLanguage("");
        assertNotNull(result);
        // Depending on availableLocaleList, this is likely empty
        assertTrue(result.isEmpty() || result.stream().allMatch(l -> l.getLanguage().equals("")));
    }
}
